def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # A diamond is a color-2 pixel with four diagonal? Detect diamonds as 4 arms
    centers = []
    for r in range(1, h-1):
        for c in range(1, w-1):
            if (grid[r-1][c] == 2 and grid[r+1][c] == 2 and
                grid[r][c-1] == 2 and grid[r][c+1] == 2 and grid[r][c] == 0):
                centers.append((r,c))
    # Join diamond centers that share a row or column, coloring only the gap.
    for i, (r,c) in enumerate(centers):
        for rr,cc in centers[i+1:]:
            if r == rr:
                for x in range(min(c,cc)+2, max(c,cc)-1):
                    if out[r][x] == 0: out[r][x] = 1
            elif c == cc:
                for x in range(min(r,rr)+2, max(r,rr)-1):
                    if out[x][c] == 0: out[x][c] = 1
    return out
